import base64, requests

# ── Cole aqui o valor do pipeline_artifact ────────────────────────────────────
B64 = ""
# ─────────────────────────────────────────────────────────────────────────────

artifact = base64.b64decode(B64)

novos_clientes = """\
customer_id,age,senior_citizen,tenure_months,contract_type,internet_service,tech_support,payment_method,paperless_billing,num_products,monthly_charges,total_charges,calls_to_support
C001,28,0,2,Month-to-month,Fiber optic,No,Electronic check,Yes,1,85.0,170.0,6
C002,45,0,36,Two year,DSL,Yes,Bank transfer,No,3,55.0,1980.0,0
C003,62,1,1,Month-to-month,Fiber optic,No,Electronic check,Yes,1,90.0,90.0,9
C004,34,0,24,One year,DSL,Yes,Credit card,No,2,65.0,1560.0,1
C005,51,1,3,Month-to-month,No,No,Mailed check,No,1,25.0,75.0,4
"""

resp = requests.post(
    "http://localhost:8000/api/v1/predict",
    files={
        "prediction_data": ("novos_clientes.csv", novos_clientes.encode(), "text/csv"),
        "pipeline_artifact": ("pipeline.joblib", artifact, "application/octet-stream"),
    }
)

result = resp.json()
print("HTTP:", resp.status_code)
print("Status:", result.get("status"))
print()

predicoes = result.get("predictions", {}).get("values", [])
clientes = ["C001","C002","C003","C004","C005"]
for cliente, pred in zip(clientes, predicoes):
    label = "⚠  CHURN" if pred == 1 else "✓  retém"
    print(f"  {cliente}: {label}  (raw={pred})")

if result.get("predictions", {}).get("csv"):
    print("\nCSV:\n" + result["predictions"]["csv"])

